from flask import Flask, redirect, url_for

app = Flask(__name__)

@app.route('/new')
def new_endpoint():
    return "Welcome to the new route"

@app.route('/old')
def old_endpoint():
    return redirect(url_for('new_endpoint'))

if __name__ == '__main__':
    app.run(debug=True)
